-- Khabar → PlanetScale schema (clean rebuild, no RLS / no Supabase extensions)
-- Tables only; foreign keys + indexes are added in 02_constraints.sql AFTER data load.
-- Re-runnable: wipes and rebuilds the public schema each run.

DROP SCHEMA IF EXISTS public CASCADE;
CREATE SCHEMA public;

CREATE TABLE public.products (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, brand text NOT NULL, external_id text NOT NULL, name text NOT NULL, category_raw text, category_normalized text, gender text, sizes_available jsonb, url text, image_url text, first_seen_at timestamptz DEFAULT now(), last_seen_at timestamptz DEFAULT now(), is_active boolean DEFAULT true, delisted_at timestamptz, first_observed_price numeric, attributes_extracted jsonb, source_published_at timestamptz, department text, subcategory text);
CREATE TABLE public.price_events (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id bigint, brand text NOT NULL, price_before numeric, price_after numeric NOT NULL, compare_at_price numeric, discount_pct numeric, direction text, sizes_in_stock jsonb, recorded_at timestamptz DEFAULT now(), is_statistical_deal boolean DEFAULT false, is_flash_sale boolean DEFAULT false);
CREATE TABLE public.users (telegram_id bigint PRIMARY KEY, username text, tier text DEFAULT 'free'::text, paid_until date, brands_monitored jsonb DEFAULT '[]'::jsonb, categories_selected jsonb DEFAULT '[]'::jsonb, sizes jsonb DEFAULT '{}'::jsonb, price_ceiling numeric, joined_at timestamptz DEFAULT now(), last_active_at timestamptz DEFAULT now(), referral_code text, referred_by text, conversation_state text DEFAULT 'new'::text, temp_data jsonb DEFAULT '{}'::jsonb);
CREATE TABLE public.alert_queue (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id bigint, price_event_id bigint, send_at timestamptz NOT NULL, sent boolean DEFAULT false);
CREATE TABLE public.sale_periods (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, brand text NOT NULL, started_at timestamptz, ended_at timestamptz, peak_discount_pct numeric, categories_affected jsonb, products_count integer);
CREATE TABLE public.bot_state (key text PRIMARY KEY, value text);
CREATE TABLE public.product_variants (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id bigint, external_sku text NOT NULL, color text, size text, is_in_stock boolean DEFAULT true, last_updated_at timestamptz DEFAULT now(), first_observed_price numeric, delisted_at timestamptz, color_family text, color_shade text, url text, size_family text, size_system text, size_status text);
CREATE TABLE public.price_snapshots (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id bigint, variant_id bigint, brand text NOT NULL, price numeric NOT NULL, compare_at_price numeric, discount_pct numeric, snapshot_date date NOT NULL DEFAULT CURRENT_DATE, recorded_at timestamptz DEFAULT now());
CREATE TABLE public.user_brands (user_id bigint NOT NULL, brand text NOT NULL, PRIMARY KEY (user_id, brand));
CREATE TABLE public.user_sizes (user_id bigint NOT NULL, category text NOT NULL, size text NOT NULL, PRIMARY KEY (user_id, category));
CREATE TABLE public.stockout_events (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, variant_id bigint, product_id bigint, brand text NOT NULL, size text, color text, event_type text NOT NULL, price_at_event numeric, discount_pct_at_event numeric, was_on_discount boolean DEFAULT false, recorded_at timestamptz DEFAULT now(), witnessed boolean, seed_reason text);
CREATE TABLE public.dashboard_users (username text PRIMARY KEY, password_hash text NOT NULL, full_name text, company text, tier text DEFAULT 'basic'::text, categories jsonb DEFAULT '[]'::jsonb, brand_tier text, gender_focus text, watch_list jsonb DEFAULT '[]'::jsonb, created_at timestamptz DEFAULT now(), last_login timestamptz);
CREATE TABLE public.weekly_product_summary (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id bigint, brand text NOT NULL, category_normalized text, gender text, week_start date NOT NULL, iso_week integer, iso_year integer, price_median numeric, price_min numeric, price_max numeric, price_open numeric, price_close numeric, first_observed_price numeric, discount_event_count integer DEFAULT 0, max_discount_pct numeric, avg_discount_depth_pct numeric, days_on_discount integer DEFAULT 0, sizes_total integer, sizes_in_stock_avg numeric, stockout_count integer DEFAULT 0, restock_count integer DEFAULT 0, is_active boolean DEFAULT true, delisted boolean DEFAULT false, sample_days integer DEFAULT 0, recorded_at timestamptz DEFAULT now());
CREATE TABLE public.weekly_variant_exception (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, variant_id bigint, product_id bigint, week_start date NOT NULL, iso_week integer, iso_year integer, size text, color text, price numeric, is_in_stock boolean, days_in_stock integer, stockout_count integer DEFAULT 0, restock_count integer DEFAULT 0, recorded_at timestamptz DEFAULT now(), price_median numeric, price_min numeric, price_max numeric, discount_depth_pct numeric, price_diverged boolean DEFAULT false);
CREATE TABLE public.scraper_health_log (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, checked_at timestamptz NOT NULL DEFAULT now(), brand text NOT NULL, products integer, variants integer, pct_sized numeric, pct_colored numeric, last_snapshot_date date, snapshot_age_days integer, latest_day_snapshot_count integer, price_events_7d integer);
CREATE TABLE public.bestseller_rank (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id bigint NOT NULL, brand text NOT NULL, rank integer NOT NULL, snapshot_date date NOT NULL DEFAULT CURRENT_DATE, recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.fx_rate (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, rate_date date NOT NULL, usd_egp numeric NOT NULL, source text NOT NULL DEFAULT 'frankfurter'::text, recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.meta_ad_activity (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, brand text NOT NULL, snapshot_date date NOT NULL DEFAULT CURRENT_DATE, active_ad_count integer, earliest_ad_start date, sample_ad_texts jsonb, page_id text, recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.color_map (color_raw text PRIMARY KEY, color_family text, color_shade text, is_compound boolean NOT NULL DEFAULT false, secondary_family text, status text NOT NULL DEFAULT 'unclassified'::text, source text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.category_map (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, match_type text NOT NULL, pattern text NOT NULL, department text, category text, subcategory text, priority integer NOT NULL DEFAULT 100, status text NOT NULL DEFAULT 'classified'::text, source text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.weekly_bestseller_summary (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id bigint NOT NULL, brand text NOT NULL, week_start date NOT NULL, iso_week integer NOT NULL, iso_year integer NOT NULL, rank_best integer, rank_worst integer, rank_avg numeric, rank_close integer, rank_change_vs_prev_week integer, sample_days integer NOT NULL, recorded_at timestamptz DEFAULT now());
CREATE TABLE public.signal_runs (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, signal_id text NOT NULL, signal_name text NOT NULL, level text NOT NULL, status text NOT NULL, skip_reason text, rows_written integer DEFAULT 0, rows_suppressed integer DEFAULT 0, window_start date, window_end date, days_available integer, duration_seconds numeric, error_message text, run_at timestamptz DEFAULT now());
CREATE TABLE public.signal_l1_07_price_anomaly (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id bigint NOT NULL, brand text NOT NULL, product_name text, category_normalized text, gender text, snapshot_date date NOT NULL, current_price numeric NOT NULL, median_price numeric, q1_price numeric, q3_price numeric, iqr numeric, lower_fence numeric, deviation_pct numeric, is_lowest_ever boolean DEFAULT false, days_observed integer NOT NULL, window_days integer NOT NULL, computed_at timestamptz DEFAULT now(), band_move_size integer DEFAULT 1, is_band_move boolean DEFAULT false);
CREATE TABLE public.signal_l1_01_genuine_price_drop (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id bigint, brand text NOT NULL, product_name text, category_normalized text, gender text, snapshot_date date NOT NULL, current_price numeric, baseline_price numeric, drop_pct numeric, computed_at timestamptz DEFAULT now());
CREATE TABLE public.signal_l1_03_price_staircase (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id bigint, brand text NOT NULL, product_name text, category_normalized text, gender text, snapshot_date date NOT NULL, step_count integer, first_price numeric, last_price numeric, total_descent_pct numeric, first_step_at timestamptz, last_step_at timestamptz, span_days integer, computed_at timestamptz DEFAULT now());
CREATE TABLE public.signal_l1_17_depth_escalation (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id bigint, brand text NOT NULL, product_name text, category_normalized text, gender text, snapshot_date date NOT NULL, escalation_count integer, first_depth_pct numeric, last_depth_pct numeric, first_step_at timestamptz, last_step_at timestamptz, span_days integer, computed_at timestamptz DEFAULT now());
CREATE TABLE public.lcw_scrape_progress (scrape_date date NOT NULL, category_id integer NOT NULL, category_name text, status text NOT NULL CHECK (status = ANY (ARRAY['complete'::text, 'partial'::text])), pages_done integer NOT NULL DEFAULT 0, pages_total integer NOT NULL DEFAULT 0, pages_failed integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now(), slot text NOT NULL DEFAULT 'pm'::text);
CREATE TABLE public.category_department_map (category_normalized text PRIMARY KEY, department text NOT NULL, source text DEFAULT 'majority_vote'::text, created_at timestamptz DEFAULT now());
CREATE TABLE public.pipeline_health (captured_on date NOT NULL, brand text NOT NULL, products_active integer, variants_total integer, variants_stock_known integer, variants_oos integer, snapshots_today integer, snapshots_discounted integer, price_events_today integer, stockouts_today integer, restocks_today integer, delists_today integer, witnessed_today integer, dept_null_pct numeric, hours_since_scrape numeric, PRIMARY KEY (captured_on, brand));
CREATE TABLE public.signal_l1_08_variant_stockout (snapshot_date date NOT NULL, brand text NOT NULL, category_normalized text NOT NULL, gender text NOT NULL, stockout_events integer, variants_affected integer, products_affected integer, on_discount_events integer, on_discount_pct numeric, observed_days integer, window_days integer, PRIMARY KEY (snapshot_date, brand, category_normalized, gender));
CREATE TABLE public.signal_l1_09_variant_restock (snapshot_date date NOT NULL, brand text NOT NULL, category_normalized text NOT NULL, closed_pairs integer, open_stockouts integer, completion_rate_pct numeric, median_restock_days numeric, p25_restock_days numeric, p75_restock_days numeric, fastest_restock_days numeric, observed_days integer, window_days integer, PRIMARY KEY (snapshot_date, brand, category_normalized));
CREATE TABLE public.mass_event_review (brand text NOT NULL, day date NOT NULL, event_type text NOT NULL, events integer, ratio numeric, status text DEFAULT 'pending_review'::text, verdict text, reviewed_on date, first_seen date DEFAULT CURRENT_DATE, PRIMARY KEY (brand, day, event_type));
CREATE TABLE public.signal_l1_12_new_sku_launch (product_id bigint NOT NULL, brand text, product_name text, department text, category_normalized text, subcategory text, launch_price numeric, launch_date date, snapshot_date date NOT NULL, PRIMARY KEY (product_id, snapshot_date));
CREATE TABLE public.signal_l1_13_product_delisted (product_id bigint NOT NULL, brand text, product_name text, department text, category_normalized text, subcategory text, first_observed_price numeric, final_price numeric, final_discount_pct numeric, delisted_date date, snapshot_date date NOT NULL, PRIMARY KEY (product_id, snapshot_date));
CREATE TABLE public.signal_l1_10_dead_stock (product_id bigint NOT NULL, brand text, product_name text, department text, category_normalized text, subcategory text, honest_discount_pct numeric, variant_count integer, in_stock_count integer, snapshot_date date NOT NULL, PRIMARY KEY (product_id, snapshot_date));
CREATE TABLE public.signal_l1_04_anchor_inflation (product_id bigint NOT NULL, brand text, product_name text, department text, category_normalized text, subcategory text, prev_compare_at numeric, new_compare_at numeric, actual_price numeric, anchor_inflation_pct numeric, snapshot_date date NOT NULL, PRIMARY KEY (product_id, snapshot_date));
CREATE TABLE public.signal_l1_22_discount_velocity (brand text NOT NULL, department text, category_normalized text NOT NULL, subcategory text NOT NULL DEFAULT '(none)'::text, window_start timestamptz NOT NULL, skus_dropped integer, snapshot_date date NOT NULL, PRIMARY KEY (brand, category_normalized, subcategory, window_start));
CREATE TABLE public.signal_l1_24_restock_density (brand text NOT NULL, department text, category_normalized text NOT NULL, subcategory text NOT NULL DEFAULT '(none)'::text, color text NOT NULL DEFAULT '(none)'::text, restock_date date NOT NULL, variants_restocked integer, products_affected integer, snapshot_date date NOT NULL, PRIMARY KEY (brand, category_normalized, subcategory, color, restock_date));
CREATE TABLE public.signal_l1_11_size_asymmetry (product_id bigint NOT NULL, brand text, product_name text, department text, category_normalized text, subcategory text, stocked_out_size text NOT NULL, stocked_out_color text, sizes_still_in_stock text[], event_date date, snapshot_date date NOT NULL, PRIMARY KEY (product_id, stocked_out_size, snapshot_date));
CREATE TABLE public.signal_l1_06_discount_recovery (product_id bigint NOT NULL, brand text, product_name text, department text, category_normalized text, subcategory text, first_observed_price numeric, low_price numeric, recovered_price numeric, structural_reprice_pct numeric, recovery_date date, snapshot_date date NOT NULL, PRIMARY KEY (product_id, snapshot_date));
CREATE TABLE public.signal_l1_14_launch_to_discount (product_id bigint NOT NULL, brand text, product_name text, department text, category_normalized text, subcategory text, launch_date date, first_discount_date date, days_to_first_discount integer, snapshot_date date NOT NULL, PRIMARY KEY (product_id, snapshot_date));
CREATE TABLE public.product_runs (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id text NOT NULL, product_name text, status text NOT NULL, skip_reason text, rows_written integer DEFAULT 0, duration_seconds numeric, error_message text, run_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.product_l2_01_price_elasticity (brand text NOT NULL, category_normalized text NOT NULL, gender text NOT NULL, products_with_drops integer, avg_drop_pct numeric, max_drop_pct numeric, stockout_events integer, products_stocking_out integer, pct_stockouts_while_discounted numeric, elasticity_read text, report_date date NOT NULL, PRIMARY KEY (brand, category_normalized, gender, report_date));
CREATE TABLE public.product_l2_08_brand_health (brand text NOT NULL, category_normalized text NOT NULL, products_dropping integer, avg_drop_pct numeric, anchor_inflation_events integer, dead_stock_products integer, avg_dead_discount_pct numeric, restock_completion_pct numeric, median_restock_days numeric, escalating_products integer, health_score_0_100 integer, report_date date NOT NULL, PRIMARY KEY (brand, category_normalized, report_date));
CREATE TABLE public.product_l2_09_revealed_demand (brand text NOT NULL, category_normalized text NOT NULL, stocked_out_size text NOT NULL, stockout_count integer, products_affected integer, while_other_sizes_available integer, pct_size_specific_demand numeric, category_stockout_events integer, category_pct_stockouts_while_discounted numeric, category_price_anomalies integer, report_date date NOT NULL, PRIMARY KEY (brand, category_normalized, stocked_out_size, report_date));
CREATE TABLE public.product_l2_13_wallet_allocator (brand text NOT NULL, category_normalized text NOT NULL, stocked_out_size text NOT NULL, stockout_count integer, new_skus_launched_in_category integer, avg_launch_price numeric, category_pct_stockouts_while_discounted numeric, allocation_read text, report_date date NOT NULL, PRIMARY KEY (brand, category_normalized, stocked_out_size, report_date));
CREATE TABLE public.product_l2_10_market_entry (brand text NOT NULL, category_normalized text NOT NULL, new_skus_launched integer, avg_launch_price numeric, skus_delisted integer, net_catalogue_change integer, dead_stock_products integer, trajectory text, report_date date NOT NULL, PRIMARY KEY (brand, category_normalized, report_date));
CREATE TABLE public.product_l2_12_liquidation_calendar (brand text NOT NULL, category_normalized text NOT NULL, escalating_products integer, avg_current_depth_pct numeric, dead_stock_products integer, staircase_products integer, skus_in_discount_bursts integer, variants_restocked_recently integer, distress_level text, report_date date NOT NULL, PRIMARY KEY (brand, category_normalized, report_date));
CREATE TABLE public.product_l2_02_production_blueprint (brand text NOT NULL, category_normalized text NOT NULL, stocked_out_size text NOT NULL, undersupply_signal integer, oversupply_signal_category integer, new_skus_launched_category integer, delisted_skus_category integer, production_signal text, report_date date NOT NULL, PRIMARY KEY (brand, category_normalized, stocked_out_size, report_date));
CREATE TABLE public.signal_l2_pricing_discipline (brand text NOT NULL, category_normalized text NOT NULL, discount_events integer, avg_depth_pct numeric, median_depth_pct numeric, depth_stddev numeric, discipline_read text, snapshot_date date NOT NULL, PRIMARY KEY (brand, category_normalized, snapshot_date));
CREATE TABLE public.signal_l2_first_mover (category_normalized text NOT NULL, brand text NOT NULL, discount_days integer, first_discount_date date, avg_days_after_category_first numeric, mover_read text, snapshot_date date NOT NULL, PRIMARY KEY (category_normalized, brand, snapshot_date));
CREATE TABLE public.signal_l2_trained_customer (brand text NOT NULL, discount_events integer, active_days integer, span_days integer, pct_days_discounting numeric, avg_depth_pct numeric, depth_consistency numeric, risk_read text, snapshot_date date NOT NULL, PRIMARY KEY (brand, snapshot_date));
CREATE TABLE public.taxonomy_audit (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id bigint, category_label text, vision_verdict text, agrees boolean, audited_at timestamptz DEFAULT now());
CREATE TABLE public.signal_l2_discount_honesty (brand text NOT NULL, category_normalized text NOT NULL, scored_events integer NOT NULL, avg_claimed_depth_pct numeric, avg_genuine_depth_pct numeric, manufactured_gap_pct numeric, pct_pure_fake numeric, honesty_read text, snapshot_date date NOT NULL, PRIMARY KEY (brand, category_normalized, snapshot_date));
CREATE TABLE public.size_review_queue (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, size_raw text NOT NULL, category_normalized text, brand text, sample_count integer, reason text, status text DEFAULT 'pending'::text, created_at timestamptz DEFAULT now());
CREATE TABLE public.signal_l2_market_velocity (week_start date NOT NULL, stockouts integer, restocks integer, variants_stocked_out integer, stockout_restock_ratio numeric, wow_stockout_delta integer, wow_pct numeric, velocity_read text, snapshot_date date NOT NULL, PRIMARY KEY (week_start, snapshot_date));
CREATE TABLE public.signal_l2_replenishment_benchmark (brand text NOT NULL, cycles integer, median_replen_days numeric, market_median_days numeric, vs_market_ratio numeric, replenishment_read text, snapshot_date date NOT NULL, PRIMARY KEY (brand, snapshot_date));
CREATE TABLE public.signal_l2_share_of_launch (category_normalized text NOT NULL, brand text NOT NULL, brand_launches integer, category_launches integer, share_pct numeric, launch_read text, snapshot_date date NOT NULL, PRIMARY KEY (category_normalized, brand, snapshot_date));
CREATE TABLE public.signal_l2_size_demand_curve (size_system text NOT NULL, size_family text NOT NULL, stockouts integer, brands integer, demand_share_pct numeric, snapshot_date date NOT NULL, PRIMARY KEY (size_system, size_family, snapshot_date));
